import React, { useEffect, useState } from 'react';
import { useLanguage } from '../context/LanguageContext';
import '../styles/home.css';

const Home = () => {
  const { t, appData } = useLanguage();
  const [dialoguesPreview, setDialoguesPreview] = useState([]);
  const [storiesPreview, setStoriesPreview] = useState([]);
  const [flashcardsPreview, setFlashcardsPreview] = useState([]);

  const loadData = () => {
    // Mock data for demonstration
    const mockData = {
      dialogues: [
        { id: 1, title: 'Restaurant Conversation', level: 'Beginner', duration: '5 min' },
        { id: 2, title: 'Job Interview', level: 'Intermediate', duration: '8 min' },
        { id: 3, title: 'Travel Planning', level: 'Advanced', duration: '12 min' }
      ],
      stories: [
        { id: 1, title: 'The Lost Cat', level: 'Beginner', readTime: '3 min' },
        { id: 2, title: 'A Day in Paris', level: 'Intermediate', readTime: '7 min' },
        { id: 3, title: 'The Mystery Novel', level: 'Advanced', readTime: '15 min' }
      ],
      flashcards: [
        { id: 1, name: 'Basic Vocabulary', cards: 50, lastStudied: '2 days ago' },
        { id: 2, name: 'Business Terms', cards: 75, lastStudied: '1 week ago' },
        { id: 3, name: 'Travel Phrases', cards: 30, lastStudied: 'Never' }
      ]
    };

    setDialoguesPreview(mockData.dialogues);
    setStoriesPreview(mockData.stories);
    setFlashcardsPreview(mockData.flashcards);
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <div className="home-page">
      {/* Hero Section */}
      <section className="hero">
        <div className="hero-content">
          <h1 data-translate="heroTitle">
            {t('heroTitle', 'Aprenda idiomas de forma natural e divertida')}
          </h1>
          <p data-translate="heroSubtitle">
            {t('heroSubtitle', 'Domine novos idiomas através de diálogos reais, histórias envolventes e flashcards inteligentes.')}
          </p>
          <div className="cta-buttons">
             <button className="btn btn-primary" data-translate="getStarted">
               {t('getStarted', 'Começar Agora')}
             </button>
             <button className="btn btn-secondary" data-translate="learnMore">
               {t('learnMore', 'Saiba Mais')}
             </button>
           </div>
        </div>
        <div className="hero-image">
          <i className="fas fa-globe-americas"></i>
        </div>
      </section>

      {/* Features Section */}
      <section className="features">
        <div className="container">
          <div className="section-title">
            <h2 data-translate="featuresTitle">{t('featuresTitle', 'Por que escolher LinguaNova?')}</h2>
            <p data-translate="featuresSubtitle">{t('featuresSubtitle', 'Uma abordagem completa para o aprendizado de idiomas')}</p>
          </div>

          <div className="features-grid">
            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-comments"></i>
              </div>
              <h3 data-translate="navDialogues">{t('navDialogues', 'Diálogos')}</h3>
              <p data-translate="dialoguesFeatureDesc">{t('dialoguesFeatureDesc', 'Aprenda com conversas autênticas em situações do dia a dia. Pratique pronúncia e compreensão auditiva.')}</p>
            </div>

            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-book-open"></i>
              </div>
              <h3 data-translate="navStories">{t('navStories', 'Histórias')}</h3>
              <p data-translate="storiesFeatureDesc">{t('storiesFeatureDesc', 'Histórias curtas e envolventes escritas especificamente para o seu nível de aprendizado.')}</p>
            </div>

            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-layer-group"></i>
              </div>
              <h3 data-translate="navMyDecks">{t('navMyDecks', 'Flashcards')}</h3>
              <p data-translate="flashcardsFeatureDesc">{t('flashcardsFeatureDesc', 'Flashcards inteligentes que se adaptam ao seu ritmo de aprendizado e reforçam o vocabulário.')}</p>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
